using LibreKO.Editors.Contracts;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using MySqlConnector;
namespace LibreKO.Editors.DataHost;
internal record InspectedSchema(string Database,string ServerVersion,IReadOnlyList<CompatibilityColumn> Columns,IReadOnlyDictionary<string,string> Engines);
internal static class SchemaInspection {
 public static CompatibilityColumn[] Expected(IEntityType entity, string[]? properties=null){var table=entity.GetTableName()!;var store=StoreObjectIdentifier.Table(table,null);var key=entity.FindPrimaryKey()!.Properties;return entity.GetProperties().Where(p=>properties==null||properties.Contains(p.Name)).Select(p=>new CompatibilityColumn(table,p.GetColumnName(store)!,p.GetColumnType()??p.GetRelationalTypeMapping().StoreType,p.IsNullable,key.Contains(p),p.GetDefaultValue()!=null||p.GetDefaultValueSql()!=null,p.ValueGenerated!=ValueGenerated.Never)).ToArray();}
 public static async Task<InspectedSchema> ReadAsync(string connectionString,IEnumerable<string> requested){await using var connection=new MySqlConnection(connectionString);await connection.OpenAsync();var lower=Convert.ToInt32(await new MySqlCommand("SELECT @@lower_case_table_names",connection).ExecuteScalarAsync());var names=requested.Distinct().ToDictionary(n=>n,n=>n,lower==0?StringComparer.Ordinal:StringComparer.OrdinalIgnoreCase);var actual=new List<CompatibilityColumn>();var engines=new Dictionary<string,string>();await using var command=new MySqlCommand("SELECT c.TABLE_NAME,c.COLUMN_NAME,c.COLUMN_TYPE,c.IS_NULLABLE,c.COLUMN_KEY,c.COLUMN_DEFAULT,c.EXTRA,t.ENGINE FROM information_schema.COLUMNS c JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=c.TABLE_SCHEMA AND t.TABLE_NAME=c.TABLE_NAME WHERE c.TABLE_SCHEMA=DATABASE()",connection);await using var reader=await command.ExecuteReaderAsync();while(await reader.ReadAsync()){if(!names.TryGetValue(reader.GetString(0),out var table))continue;var extra=reader.IsDBNull(6)?"":reader.GetString(6);actual.Add(new(table,reader.GetString(1),reader.GetString(2),reader.GetString(3)=="YES",reader.GetString(4)=="PRI",!reader.IsDBNull(5),extra.Contains("auto_increment",StringComparison.OrdinalIgnoreCase)||extra.Contains("STORED GENERATED",StringComparison.OrdinalIgnoreCase)||extra.Contains("VIRTUAL GENERATED",StringComparison.OrdinalIgnoreCase)));engines[table]=reader.IsDBNull(7)?"VIEW":reader.GetString(7);}return new(connection.Database,connection.ServerVersion,actual,engines);}
}
